Object.keys(NGHEDE).forEach(function (d) {
  if (NGHEDE[d]) NGHEDE[d].split(',').forEach(function (m) { AUDIO.push(d + m + '.mp3.bin'); });
});
var ACACHE = 'onthi2026a-audio';
/* Cloudflare Pages phát file nghe / video / Nghe đề (người dùng chốt 15/11/2026; media.js tải từ đây trước, lỗi thì từ GitHub):
   {"<địa chỉ dự án Cloudflare>": "<tiền tố tương ứng trên trang, tính từ gốc>"}. Tệp tải từ Cloudflare lưu đệm dưới URL CÙNG TRANG
   tương ứng → tệp đã lưu từ GitHub dùng lại được (không tải lại), dọn bộ đệm theo AUDIO như cũ. {} = không dùng Cloudflare. */
var CDN = {"https://thiqh2026-nghe-de.pages.dev/": "nghe-de/", "https://thiqh2026.pages.dev/": ""};
function tuongDuong(href) {
  for (var b in CDN) if (href.indexOf(b) === 0) return self.registration.scope + CDN[b] + href.slice(b.length);
  return null;
}
/* chỉ lưu tệp media thật: mạng nội bộ chặn tên miền có thể trả trang HTML báo chặn (mã 200) → không lưu, để media.js lấy lại từ GitHub */
function luuDuoc(r) { return !!(r && r.ok && !/text\/html/i.test(r.headers.get('Content-Type') || '')); }

function laTrang(f) { return f === './' || /\.html?$/.test(f); }
function tenTep(u) { return u.slice(self.registration.scope.length) || './'; }   /* URL tuyệt đối → tên như trong FILES ('' = './') */

self.addEventListener('install', function (e) {
  e.waitUntil(caches.open(PCACHE).then(function (pc) {
    return caches.keys().then(function (keys) {             /* 1) chép trang bản cũ đã lưu sang PCACHE — không tải mạng */
      return Promise.all(keys.filter(function (k) { return k.indexOf(OLD) === 0; }).map(function (k) {
        return caches.open(k).then(function (c) {
          return c.keys().then(function (reqs) {
            return Promise.all(reqs.map(function (r) {
              return pc.match(r).then(function (co) {
                return co || c.match(r).then(function (res) { if (res) return pc.put(r, res); });
              });
            }));
          });
        });
      }));
    }).then(function () {                                    /* 2) tệp nhỏ: hỏi lại máy chủ (304 nếu không đổi) */
      return Promise.all(FILES.filter(function (f) { return !laTrang(f); }).map(function (f) {
        return fetch(new Request(f, { cache: 'no-cache' })).then(function (r) { if (r.ok) return pc.put(f, r); }).catch(function () {});
      }));
    });
  }).catch(function () {}).then(function () { return self.skipWaiting(); }));
});

self.addEventListener('activate', function (e) {
  e.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) { return k.indexOf(OLD) === 0; }).map(function (k) { return caches.delete(k); }));
  }).then(function () {
    return caches.open(PCACHE).then(function (c) {           /* dọn trang / tệp không còn trên web */
      return c.keys().then(function (reqs) {
        return Promise.all(reqs.filter(function (r) { return FILES.indexOf(tenTep(r.url)) < 0; }).map(function (r) { return c.delete(r); }));
      });
    });
  }).then(function () {
    return caches.open(ACACHE).then(function (c) {
      return c.keys().then(function (reqs) {
        return Promise.all(reqs.filter(function (r) { return AUDIO.indexOf(r.url.slice(self.registration.scope.length)) < 0; })
          .map(function (r) { return c.delete(r); }));
      });
    });
  }).then(function () { return self.clients.claim(); }));
});

function withTimeout(ms, p) {
  return new Promise(function (resolve, reject) {
    var t = setTimeout(function () { reject(new Error('timeout')); }, ms);
    p.then(function (v) { clearTimeout(t); resolve(v); }, function (err) { clearTimeout(t); reject(err); });
  });
}

self.addEventListener('fetch', function (e) {
  var req = e.request, url = new URL(req.url);
  if (req.method === 'GET' && url.origin !== self.location.origin && /\.bin$/.test(url.pathname)) {   /* tệp media từ Cloudflare */
    var td = tuongDuong(url.origin + url.pathname);
    if (!td) return;
    e.respondWith(caches.open(ACACHE).then(function (c) {
      return c.match(td).then(function (m) {
        if (m) return new Response(m.body, { status: 200, headers: { 'Content-Type': 'application/octet-stream' } });
        return fetch(req).then(function (r) { if (luuDuoc(r)) c.put(td, r.clone()); return r; });
      });
    }));
    return;
  }
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;
  if (/\/version\.json$/.test(url.pathname)) return;      /* thông báo cập nhật: luôn lấy từ mạng, không lưu đệm */
  if (/\/(audio|video|nghe-de|trang)\/.+\.bin$/.test(url.pathname)) {   /* file nghe, video, nghe đề (kho thứ hai /nghe-de/), nội dung trang (trang/): bộ đệm trước */
    e.respondWith(caches.open(ACACHE).then(function (c) {
      return c.match(req).then(function (m) {
        return m || fetch(req).then(function (r) { if (luuDuoc(r)) c.put(req, r.clone()); return r; });
      });
    }));
    return;
  }
  var page = req.mode === 'navigate' || /(\.html?|\/)$/.test(url.pathname);
  if (page) {
    var key = url.origin + url.pathname, nreq = req;
    /* mở trang: luôn hỏi lại máy chủ (không dùng bản trong bộ đệm HTTP 10 phút) → bấm "Cập nhật ngay" là có bản mới ngay.
       redirect 'manual' giữ đúng cách trình duyệt xử lý chuyển hướng của lượt mở trang. */
    if (req.mode === 'navigate') {
      try { nreq = new Request(req.url, { cache: 'no-cache', credentials: 'same-origin', redirect: 'manual' }); } catch (err) { nreq = req; }
    }
    var net = fetch(nreq).catch(function (err) { if (nreq !== req) return fetch(req); throw err; }).then(function (r) {
      /* chỉ lưu đúng trang của công cụ (vỏ màn khóa có khối id="enc"): mạng nội bộ chặn tên miền có thể trả trang báo chặn mã 200
         → trước đây trang báo chặn được lưu đè lên bản tốt, mất mạng thì mở ra trang báo chặn (review 16/11) */
      if (r && r.ok && !r.redirected && /text\/html/i.test(r.headers.get('Content-Type') || '')) {
        var copy = r.clone();
        copy.clone().text().then(function (s) {
          if (s.indexOf('id="enc"') >= 0) return caches.open(PCACHE).then(function (c) { return c.put(key, copy); });
        }).catch(function () {});
      }
      return r;
    });
    /* mạng chậm quá 6 giây → bản đã lưu của CHÍNH trang này; chưa lưu thì chờ mạng tới cùng. Chỉ khi mất mạng thật mới đưa
       trang chủ đã lưu (trước đây chậm quá 6 giây là trả trang chủ dưới địa chỉ trang khác — review 16/11) */
    e.respondWith(withTimeout(6000, net).catch(function () {
      return caches.match(key).then(function (m) {
        return m || net.catch(function (err) {
          return caches.match(new URL('index.html', self.registration.scope).href).then(function (i) { if (i) return i; throw err; });
        });
      });
    }));
  } else {
    e.respondWith(caches.match(req, { ignoreSearch: true }).then(function (m) { return m || fetch(req); }));
  }
});
